head.script:
// 테스트 설명, 유효성 값 설정
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
//  - "속성과 config.xml 에 모두 값을 설정하지 않은 경우 onviewchange 적용" 은 제외 (프로젝트 config.xml 에 eventPriority=oneditend 가 설정되어 있어 재현 불가)
//  - Deprecated 예정 안내 문구는 관측 대상이 아니므로 제외
//  - GridView viewChangeAfterEdit 는 미설정(기본 false) 고정
scwin.tData = {
    "description" : "[column > P > eventPriority]<br/>inputType='select' 인 Column 에서 아이템 선택 후 먼저 발생할 이벤트를 설정합니다.",
    "validation" : [
        "onviewchange 설정 시, onviewchange 이벤트가 먼저 발생하며 이벤트는 'onviewchange > oneditend > onafteredit' 순서로 발생합니다.",
        "oneditend 설정 시, oneditend 이벤트가 먼저 발생하며 이벤트는 'oneditend > onafteredit > onviewchange' 순서로 발생합니다.",
        "미설정 시, config.xml 의 WebSquare/gridView/column[@inputType='select']/eventPriority/@value 값이 적용됩니다.",
        "onviewchange 이벤트는 선택한 아이템이 편집 전과 다른 경우에만 발생합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (eventPriority 미설정)
    con_eventPriority.setSelectedIndex(0);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - region(select) Body Column 에 eventPriority = con_eventPriority 적용 (미설정은 속성 자체를 넣지 않는다)
//  - GridView viewChangeAfterEdit 는 미설정 고정 (이벤트 순서 관측 조건 고정)
//  - oneditend / onafteredit / onviewchange 를 바인딩하여 발생 즉시 한 줄씩 출력 (출력 줄 순서 = 실제 발생 순서)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 프로젝트 config.xml 의 select Column eventPriority = oneditend\n[절차] 결과창 clear -> region 셀 편집 진입 -> 다른 아이템 또는 현재와 같은 아이템 선택\n[확인] 결과창에 이벤트가 발생 순서대로(위 -> 아래) 출력"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cEventPriority = con_eventPriority.getValue();
    let attrRegion = ' inputType="select"';
    if (cEventPriority !== '') {
        attrRegion += ' eventPriority="' + cEventPriority + '"';
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "region" : "S" },
        { "name" : "김철수", "region" : "B" },
        { "name" : "이영희", "region" : "D" }
    ], false);

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>S</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>B</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>D</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false"'
        + ' ev:oneditend="scwin.target1_oneditend" ev:onafteredit="scwin.target1_onafteredit" ev:onviewchange="scwin.target1_onviewchange"'
        + ' id="" style="width:500px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="300" style="" inputType="text" id="column2" value="region (select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="300" style="" id="region" value=""' + attrRegion + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1~3 : 발생 순서 판정 (각 핸들러가 발생 즉시 한 줄 출력)
scwin.target1_oneditend = function (rowIndex, columnIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ oneditend (row=" + rowIndex + ", colIndex=" + columnIndex + ", value=" + value + ")");
}



scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onafteredit (row=" + rowIndex + ", colIndex=" + columnIndex + ", value=" + value + ")");
}



// validation 4 : 편집 전과 같은 아이템 선택 시 이 줄이 출력되지 않음 (oldValue / newValue 로 변경 여부 확인)
//  onviewchange 는 info 객체를 전달받음 (표준 DOM 이벤트 아님)
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onviewchange (row=" + info.rowIndex + ", colIndex=" + info.colIndex + ", oldValue=" + info.oldValue + ", newValue=" + info.newValue + ")");
}
